#!/usr/bin/env sh
# Downloads the benchmark meshes into Benchmarks/Meshes (not committed).
#
# Source: Morgan McGuire, Computer Graphics Archive, https://casual-effects.com/data
#   bunny.obj   Stanford Bunny (closed version), 144 046 triangles
#   dragon.obj  Stanford Dragon, 871 306 triangles
# Original scans: Stanford 3D Scanning Repository, http://graphics.stanford.edu/data/3Dscanrep/
# Research use with attribution; not for use in commercial products without permission.
#
# The liver and box meshes are generated by the benchmark. Put a closed liver.obj into
# Benchmarks/Meshes to use a real organ mesh instead.
set -e
cd "$(dirname "$0")"
mkdir -p Meshes Downloads
for name in bunny dragon; do
    if [ -f "Meshes/$name.obj" ]; then
        echo "Meshes/$name.obj exists"
        continue
    fi
    rm -rf "Downloads/$name"
    mkdir -p "Downloads/$name"
    curl -fL -o "Downloads/$name/$name.zip" "https://casual-effects.com/g3d/data10/research/model/$name/$name.zip"
    unzip -o -q "Downloads/$name/$name.zip" -d "Downloads/$name"
    mv "Downloads/$name/$name.obj" "Meshes/$name.obj"
    echo "Meshes/$name.obj"
done
